:root{--bg-primary:#171126;--bg-surface:#30204B;--bg-accent:#FF4F87;--bg-accent-soft:#43D5C8;--spark:#FFD166;--mist:#F4EFFF;--night:#100B1A;--ground-edge:#3D235A}
*{box-sizing:border-box}html,body{width:100%;height:100%;margin:0;padding:0;overflow:hidden;background:var(--bg-primary)}.scene{position:relative;width:100%;height:100%;aspect-ratio:16/9;overflow:hidden}.scene svg{width:100%;height:100%;display:block}.orbit{fill:none;stroke:var(--bg-accent-soft);stroke-width:1.5;opacity:.12}.burst{fill:none;stroke:var(--bg-accent);stroke-width:2;opacity:.13}.micro{transform-box:fill-box;transform-origin:center;animation-name:campaignPop;animation-timing-function:ease-in-out;animation-iteration-count:infinite}.micro.alt{animation-name:confettiTurn}.left-safe{opacity:.28}.color-wash{transform-box:fill-box;transform-origin:center;animation:colorShift 7.5s ease-in-out infinite}
@keyframes campaignPop{0%,100%{transform:translate(0,5px) scale(.84);opacity:.2}50%{transform:translate(7px,-8px) scale(1.12);opacity:.82}}@keyframes confettiTurn{0%,100%{transform:translate(-4px,4px) rotate(-10deg);opacity:.22}50%{transform:translate(8px,-10px) rotate(12deg);opacity:.78}}@keyframes colorShift{0%,100%{transform:translate(-8px,0) scale(1);opacity:.26}50%{transform:translate(12px,-5px) scale(1.04);opacity:.45}}@media(prefers-reduced-motion:reduce){.micro,.color-wash{animation:none!important}}
</style></head><body><div class="scene"><svg viewBox="0 0 1920 1080" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="mktGround" x2="1" y2="1"><stop stop-color="var(--night)"/><stop offset=".58" stop-color="var(--bg-primary)"/><stop offset="1" stop-color="var(--ground-edge)"/></linearGradient><radialGradient id="mktGlow"><stop stop-color="var(--bg-accent)" stop-opacity=".32"/><stop offset="1" stop-color="var(--bg-accent)" stop-opacity="0"/></radialGradient><linearGradient id="mktSafe" x2="1"><stop stop-color="var(--night)" stop-opacity=".9"/><stop offset=".57" stop-color="var(--bg-primary)" stop-opacity=".42"/><stop offset="1" stop-color="var(--bg-primary)" stop-opacity="0"/></linearGradient><pattern id="mktDots" width="54" height="54" patternUnits="userSpaceOnUse"><circle cx="8" cy="12" r="1.2" fill="var(--mist)" opacity=".055"/><circle cx="39" cy="35" r="1" fill="var(--bg-accent-soft)" opacity=".07"/></pattern></defs>
