</svg></div><script>
(function(){var root=document.getElementById('mktMotifs'),seed=2441;function rnd(){seed=(seed*9301+49297)%233280;return seed/233280}function motif(t){if(t===0)return '<path d="M-22-6H-10L14-17V17L-10 6H-22Z" fill="none" stroke="var(--bg-accent)" stroke-width="2"/><path d="M-10 6L-6 18" stroke="var(--spark)" stroke-width="3"/>';if(t===1)return '<circle r="19" fill="none" stroke="var(--bg-accent-soft)" stroke-width="2"/><circle r="11" fill="none" stroke="var(--bg-accent)" stroke-width="2"/><circle r="3" fill="var(--spark)"/>';if(t===2)return '<path d="M-23 8L-12-7L-2 3L11-14L23-4" fill="none" stroke="var(--mist)" stroke-width="2"/><path d="M15-14H23V-6" fill="none" stroke="var(--bg-accent)" stroke-width="2"/>';return '<rect x="-18" y="-4" width="9" height="9" rx="2" fill="var(--bg-accent)"/><path d="M0-16l6 12-12 0Z" fill="var(--spark)"/><circle cx="15" cy="10" r="5" fill="var(--bg-accent-soft)"/>'}for(var r=0;r<6;r++){for(var c=0;c<8;c++){var x=70+c*248+(rnd()-.5)*72,y=82+r*180+(rnd()-.5)*60,t=Math.floor(rnd()*4),o=document.createElementNS('http://www.w3.org/2000/svg','g'),i=document.createElementNS('http://www.w3.org/2000/svg','g');o.setAttribute('transform','translate('+x+' '+y+')');i.setAttribute('class','micro '+(t%2?'alt ':'')+(x<1056?'left-safe':''));i.style.animationDuration=(4+rnd()*5).toFixed(2)+'s';i.style.animationDelay=(-rnd()*9).toFixed(2)+'s';i.innerHTML=motif(t);o.appendChild(i);root.appendChild(o)}}})();
